import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.7nMnW4XS.js";const m=JSON.parse('{"title":"Post-#332 follow-ups (June 2026)","description":"","frontmatter":{},"headers":[],"relativePath":"guides/post-332-follow-ups.md","filePath":"guides/post-332-follow-ups.md"}'),r={name:"guides/post-332-follow-ups.md"};function i(n,e,c,l,d,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="post-332-follow-ups-june-2026" tabindex="-1">Post-#332 follow-ups (June 2026) <a class="header-anchor" href="#post-332-follow-ups-june-2026" aria-label="Permalink to &quot;Post-#332 follow-ups (June 2026)&quot;">​</a></h1><p>Punch list captured after the foundational-refactors PR landed on main. Items 1–4 are tracked separately by Marko + the other agent; items 5–9 are open here for future sessions.</p><h2 id="tracked-elsewhere-marko-other-agent" tabindex="-1">Tracked elsewhere (Marko + other agent) <a class="header-anchor" href="#tracked-elsewhere-marko-other-agent" aria-label="Permalink to &quot;Tracked elsewhere (Marko + other agent)&quot;">​</a></h2><h3 id="_1-2d-debug-helper-orbital-math-extraction" tabindex="-1">1. 2D-debug helper / orbital math extraction <a class="header-anchor" href="#_1-2d-debug-helper-orbital-math-extraction" aria-label="Permalink to &quot;1. 2D-debug helper / orbital math extraction&quot;">​</a></h3><p>Extract Kepler propagation, spacecraft position, camera position, and screen projection into pure fns under <code>$lib/orbital/</code>. Render a minimal black-and- white 2D view of route / planet / ship / camera so the math is verifiable without the 3D stack. The 2D view consumes the same fns the 3D scene will eventually call — sanity check: if 2D and 3D disagree about Curiosity at MET=100 days, the bug is in the renderer, not the math. Doubles as a production helper for debug overlays + future test harnesses.</p><h3 id="_2-327-—-data-ts-split-dal-architecture-review" tabindex="-1">2. #327 — data.ts split + DAL architecture review <a class="header-anchor" href="#_2-327-—-data-ts-split-dal-architecture-review" aria-label="Permalink to &quot;2. #327 — data.ts split + DAL architecture review&quot;">​</a></h3><p>Phase 0 ADR answering the 7 architectural questions captured in the issue body (per-domain vs shared cache, query-key pattern vs lazy singletons, locale-overlay helper extraction, barrel-or-sweep, provenance-stays-or-moves, cache invalidation policy, foot-gun-proof cache-import shape). Phase 1 is the mechanical 10–11 module split, barrel-keep. <code>RemoteData&lt;E,T&gt;</code> (commit 3 of #332) is the consumer shape the split should adopt.</p><h3 id="_3-fly-effect-ladder-consolidation-330-c-3" tabindex="-1">3. /fly effect-ladder consolidation (#330 C.3) <a class="header-anchor" href="#_3-fly-effect-ladder-consolidation-330-c-3" aria-label="Permalink to &quot;3. /fly effect-ladder consolidation (#330 C.3)&quot;">​</a></h3><p>Deferred from #332 commit 12. /fly has 8+ scattered <code>$effect</code> blocks reacting to overlapping state (mission load, arc changes, view-mode switches, phase markers, cinematic state). Consolidate into 2-3 coordinated effects with internal <code>switch(reason)</code> dispatch. Needs careful cinematic- timing analysis so consolidation doesn&#39;t break the iconic-shot / flyby choreography landed on main during the #332 rebase window. The lifecycle + animate-loop foundation from #332 commit 8 is in place to build on.</p><h3 id="_4-fly-apollo-11-phase-marker-jump-test-flake" tabindex="-1">4. /fly Apollo 11 phase-marker-jump test flake <a class="header-anchor" href="#_4-fly-apollo-11-phase-marker-jump-test-flake" aria-label="Permalink to &quot;4. /fly Apollo 11 phase-marker-jump test flake&quot;">​</a></h3><p><code>tests/e2e/fly-apollo11-phase-markers.spec.ts:242</code> — pre-existing on main, not introduced by #332 or the post-rebase CSS fix. <code>force: true</code> click on the phase-marker dot somehow navigates the page to <code>/missions</code> (snapshot shows LaunchesBanner). The button has <code>type=&quot;button&quot;</code> + plain <code>onclick= {onJump}</code> so the navigation is unexpected. Likely a hit-test / event bubbling issue with overlay z-stacking after the recent /fly cinematic work. Track + reproduce locally with headed Playwright.</p><h2 id="open-here-deferred-from-332" tabindex="-1">Open here (deferred from #332) <a class="header-anchor" href="#open-here-deferred-from-332" aria-label="Permalink to &quot;Open here (deferred from #332)&quot;">​</a></h2><h3 id="_5-mission-image-rework-—-missing-garbage-hero-selection" tabindex="-1">5. Mission image rework — missing + garbage + hero selection <a class="header-anchor" href="#_5-mission-image-rework-—-missing-garbage-hero-selection" aria-label="Permalink to &quot;5. Mission image rework — missing + garbage + hero selection&quot;">​</a></h3><p>Scope: combined pass over <code>static/images/missions/&lt;id&gt;.jpg</code> (card cover) + <code>static/images/missions/thumbnails/&lt;id&gt;.png</code> (trajectory thumbnail) + <code>static/images/missions/&lt;id&gt;/...</code> (per-mission gallery).</p><ul><li><strong>Missing entirely (4 missions, allowlisted in <code>tests/e2e/_helpers/console-errors.ts</code>):</strong><code>inspiration4</code>, <code>polaris-dawn</code>, <code>otv-6</code>, <code>otv-7</code>. Slice B/C shipped index entries without art; cards render with <code>cover-missing</code> graceful degradation.</li><li><strong>Garbage that passed scoring:</strong> Marko reports the existing algorithmic scoring lets through low-quality images, especially in the hero slot. Hero is the most visible asset and the worst hit.</li><li><strong>Hero selection:</strong> which image becomes the &quot;hero&quot; per mission needs a tighter selection rule, not just a score threshold.</li></ul><p>Next-step framing in progress with Marko (see &quot;Image pass — framing&quot; section in chat). Will fold into this section once the spec is set.</p><h3 id="_6-createscenecontext-createpickhandler" tabindex="-1">6. createSceneContext + createPickHandler <a class="header-anchor" href="#_6-createscenecontext-createpickhandler" aria-label="Permalink to &quot;6. createSceneContext + createPickHandler&quot;">​</a></h3><p>Deferred from #329 commit 4. Existing <code>scene-renderer.ts</code> + <code>bindCanvasInputs</code> cover the 5-of-7-route happy path. /iss + /tiangong&#39;s WebGL-availability + quality-tier-aware setup should drive the <code>createSceneContext</code> shape — easier to land alongside the first new consumer (e.g. a #325 raf + Three.js test harness) than to over-design in isolation.</p><h3 id="_7-object3duserdata-adoption-sweep" tabindex="-1">7. Object3DUserData adoption sweep <a class="header-anchor" href="#_7-object3duserdata-adoption-sweep" aria-label="Permalink to &quot;7. Object3DUserData adoption sweep&quot;">​</a></h3><p>The <code>createUserDataTag&lt;T&gt;</code> wrapper landed in #329 commit 4 with 11 tests but no callers migrated. ~27 <code>as unknown as</code> clusters across <code>iss-proxy-model.ts</code>, <code>tiangong-proxy-model.ts</code>, and <code>station-assembly-anim.ts</code> are the audit-identified targets. Mechanical sweep once #325 (raf + Three.js test harness) lands, since the wrapper makes pick-handler tests trivially easier.</p><h3 id="_8-remotedata-migration-on-iss-tiangong-plan" tabindex="-1">8. RemoteData migration on /iss, /tiangong, /plan <a class="header-anchor" href="#_8-remotedata-migration-on-iss-tiangong-plan" aria-label="Permalink to &quot;8. RemoteData migration on /iss, /tiangong, /plan&quot;">​</a></h3><p>#332 commit 10 migrated /missions + /fleet. The remaining routes have complex IO state shapes:</p><ul><li><code>/iss</code>, <code>/tiangong</code>: two parallel fetches (<code>modules</code> + <code>visitors</code>) share a single <code>loadFailed</code> flag. Each becomes its own <code>RemoteData&lt;Error, IssModule[]&gt;</code> and a derived <code>loadFailed = isError(modulesRequest) || isError(visitorsRequest)</code>.</li><li><code>/plan</code>: multiplexes <code>computing</code> / <code>progress</code> / <code>loadFailed</code> over a porkchop-grid compute + load path. RemoteData&#39;s three-state shape doesn&#39;t naturally absorb <code>progress</code>; needs a parameterised variant or separate <code>progress</code> field.</li></ul><h3 id="_9-useurlparam-sweep-beyond-surfacescene-hotspots" tabindex="-1">9. useUrlParam sweep beyond SurfaceScene hotspots <a class="header-anchor" href="#_9-useurlparam-sweep-beyond-surfacescene-hotspots" aria-label="Permalink to &quot;9. useUrlParam sweep beyond SurfaceScene hotspots&quot;">​</a></h3><p>#332 commit 11 migrated <code>SurfaceScene</code>&#39;s <code>?hotspots=</code> to <code>useUrlParam&lt;T&gt;</code> as the worked example. Other audit-flagged sites have awkward shapes:</p><ul><li>Panorama <code>?pano + ?yaw + ?pitch</code>: 3 correlated fields syncing together; useUrlParam&#39;s single-field shape doesn&#39;t fit. Needs a panorama-specific wrapper or a multi-field rune variant.</li><li>Station <code>?view + ?module</code>: already abstracted via <code>syncStationUrl</code>; migration refactors the helper rather than the route.</li><li><code>/missions</code> filter set: overlaps #332 commit 9&#39;s typed filterState bag pattern — adopting useUrlParam would mix two structures in the same file. Bag stays for filters; useUrlParam is the right tool for isolated single-field contracts.</li><li><code>/explore</code> <code>?focus= / ?paths= / ?id=</code>: read-only deep-links with no write-back; existing <code>$effect</code> pattern is already minimal.</li></ul><p>Could fold into #327&#39;s follow-up once data.ts decisions settle.</p><hr><p><em>Captured June 2026 after #332 (foundational-refactors PR) shipped to main at commit <code>0d284611a</code>.</em></p>',29)])])}const u=a(r,[["render",i]]);export{m as __pageData,u as default};
